import type { CSSObject } from '@emotion/react';
import styled from '@emotion/styled';
import type { ButtonSize } from 'components/UI';
import { Button } from 'components/UI';

const roundShapeStyles: Record<ButtonSize, CSSObject> = {
  small: {
    width: '32px',
    height: '32px',
    maxWidth: '32px',
    maxHeight: '32px',
    minWidth: '32px',
  },
  medium: {
    width: '48px',
    height: '48px',
    maxWidth: '48px',
    maxHeight: '48px',
    minWidth: '48px',
  },
  large: {
    width: '56px',
    height: '56px',
    maxWidth: '56px',
    maxHeight: '56px',
    minWidth: '56px',
  },
};

const roundOutlineStyles: CSSObject = {
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '50%',
  border: '1px solid #141414 !important',
  background: 'white !important',
  padding: '0 !important',
  boxShadow: 'none !important',
  cursor: 'pointer',

  '&:hover': {
    background: 'white !important',
    boxShadow: 'none !important',
  },
};

interface StyledButtonProps {
  $disabled?: boolean;
  $isExpanded?: boolean;
}

export const StyledButton = styled(Button, {
  shouldForwardProp: (prop) => !['$disabled', '$isExpanded'].includes(prop),
})<StyledButtonProps>(({ $disabled, $isExpanded }) => ({
  ...($isExpanded && { transform: 'rotate(180deg)' }),
  ...($disabled && {
    opacity: '0.5',
    cursor: 'not-allowed',
    pointerEvents: 'none',
  }),
}));

export const StyledRoundButton = styled(Button, {
  shouldForwardProp: (prop) => prop !== '$isExpanded',
})<{ $isExpanded?: boolean }>(({ $isExpanded, size = 'medium', disabled }) => ({
  ...roundOutlineStyles,
  ...roundShapeStyles[size as ButtonSize],
  ...($isExpanded ? { transform: 'rotate(180deg)' } : {}),
  ...(disabled
    ? {
        opacity: 0.5,
        cursor: 'not-allowed',
        pointerEvents: 'none',
      }
    : {}),
}));
